-- 8. ROW LEVEL SECURITY: public read. Writes go through the backend (service role), which
--    bypasses RLS, so anonymous clients cannot insert directly.
ALTER TABLE public.ng_states ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.feeder_zones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.power_pings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bank_telemetry_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.market_radar_reports ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read on ng_states" ON public.ng_states;
CREATE POLICY "Allow public read on ng_states" ON public.ng_states FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read on feeder_zones" ON public.feeder_zones;
CREATE POLICY "Allow public read on feeder_zones" ON public.feeder_zones FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read on power_pings" ON public.power_pings;
CREATE POLICY "Allow public read on power_pings" ON public.power_pings FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read on bank_telemetry_logs" ON public.bank_telemetry_logs;
CREATE POLICY "Allow public read on bank_telemetry_logs" ON public.bank_telemetry_logs FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public read on market_radar_reports" ON public.market_radar_reports;
CREATE POLICY "Allow public read on market_radar_reports" ON public.market_radar_reports FOR SELECT USING (true);

-- Remove the open insert policies from earlier versions of this schema
DROP POLICY IF EXISTS "Allow public insert on power_pings" ON public.power_pings;
DROP POLICY IF EXISTS "Allow public insert on bank_telemetry" ON public.bank_telemetry_logs;
DROP POLICY IF EXISTS "Allow public insert on market_radar" ON public.market_radar_reports;
